"use strict";
/* ---------------- lore: plain-English definitions, offered at the moment of need ------- */
const LORE = {
 "account":"In To The Moon, account means a platform ad account unless the screen names a broader business or reporting scope. It sits above campaigns, ad sets or ad groups, ads, and creatives.",
 "platform ad account":"A workspace inside an ad platform, usually beneath a business or administrative container and above campaigns. It can hold permissions, billing, measurement connections, and delivery history; it is not an advertiser, campaign, ad, or creative.",
 "ad":"The delivery object that enters an auction and carries creative. Changing the image, video, or copy changes the creative; it does not automatically create a new account or campaign.",
 "ad set":"A delivery group used by platforms such as Meta to hold audience, placement, schedule, and optimization settings beneath a campaign and above ads.",
 "platform":"The buying system — such as a search, social, or programmatic platform — that runs the auction, enforces policy, and reports attributed results.",
 "paid search":"Auction-based advertising against expressed search intent. Its core controls include keywords, match types, negatives, bids, Quality Score, and impression share.",
 "search intent":"The need or goal implied by a search. It can indicate readiness, research, comparison, support, employment, or another motive; click volume alone does not reveal its value.",
 "ppc":"Pay-per-click (PPC) advertising. The term is often used as shorthand for paid search, although click-priced buying can exist elsewhere too.",
 "paid social":"Auction-based advertising inside social platforms. Creative, audience signals, placements, fatigue, and optimization events usually matter more than keywords.",
 "programmatic":"Automated buying of ad inventory through exchanges, supply platforms, or demand-side platforms. It describes a buying channel and auction path, not a creative format; inventory can include display, native, video, audio, or connected TV.",
 "ctv":"Connected TV (CTV) advertising delivered to television screens through streaming inventory. It is a channel and device context, while a CTV spot is the creative made for that context; measurement often leans on reach and modeled view-through outcomes rather than clicks alone.",
 "budget":"An authorization or cap on how much may be spent. It is not the same as delivered media spend, billed cost, cash, or credit.",
 "allocation":"The portion of an available budget assigned to a particular slot, initiative, campaign, or lane. Unspent allocation remains capacity, not cost.",
 "fresh capacity":"To The Moon's estimate of how much daily allocation a buying lane can absorb before the next dollars encounter noticeably more auction friction. It is a modeled saturation boundary — not a published platform limit, a count of people, or permission to spend the full amount without checking marginal results.",
 "creative scale pressure":"A warning in To The Moon that one creative slot's allocation has moved beyond its modeled low-friction range. The next dollars may buy costlier or lower-quality delivery even when the creative still looks healthy; this differs from fatigue, which is a loss of response after repeated exposure.",
 "lane capacity pressure":"A warning in To The Moon that combined active allocation across one platform lane exceeds that lane's modeled fresh capacity. Several slots can create the pressure together, so replacing one creative may not solve it. Inspect marginal results, audience overlap, and the broader channel mix.",
 "rapid-scale review risk":"A simulated operational risk created by increasing a slot's daily budget by more than 60% at once. It can trigger a temporary delivery hold in To The Moon, showing that abrupt structural changes carry platform risk. The percentage is a game rule, not a universal live-platform threshold.",
 "media spend":"Money consumed by ad delivery. Creative production, measurement repair, and policy penalties are operating costs, not media spend.",
 "operations cost":"Non-media investment needed to support delivery and the company. In Agency Career, monthly operating obligations can include founder compensation, employee payroll and benefits, software and data, infrastructure and equipment, facilities, insurance and professional services, and approved sales, events or partnerships. These costs belong in agency economics, not client media spend.",
 "revenue":"Value recognized by the relevant business model. In To The Moon, modeled value, platform-attributed value, settled value, and cash are separate ledgers. Do not substitute one for another.",
 "settled value":"Modeled value whose waiting period has ended and that has entered the settled-value ledger. In the single-account challenges, it is a cash-like reporting value. In Portfolio Command, only collected receivables increase the cash you can spend.",
 "profit":"Value minus the stated cost base for the same scope and window. Profit is an economic result, not necessarily collected cash; modeled profit can remain positive while delayed receivables create a liquidity failure.",
 "agency profit":"In Agency Career, recognized client fees and performance incentives minus agency operating costs such as payroll, tools, sales, credits and other overhead. The monthly operating statement shows this calculation for one month. Client media spend is kept outside the ledger, so moving a client's ad budget does not manufacture agency profit or collected cash.",
 "client media spend":"Money a client authorizes for ad delivery on that client's behalf. In Agency Career it affects account outcomes and service pressure, but it is neither agency revenue nor agency operating expense and does not count directly toward the 2027 profit target.",
 "operating reserve":"Company cash set aside to keep the agency functioning while client invoices or affiliate payouts are still uncollected. It can cover bills and absorb timing shocks, but it is not client media budget, revenue, profit or permission to spend without regard to runway.",
 "monthly operating statement":"Agency Career's month-close summary of recognized agency revenue, recurring company costs, variable costs and operating profit. It explains what the agency earned and consumed during the month; it is not the cash-flow statement because some invoices may still be receivables.",
 "monthly operating obligations":"Company bills that must be covered when due, including founder compensation, employee payroll and benefits, software and data, infrastructure and equipment, facilities, insurance and professional services, and approved sales, event or partnership spending. They are agency costs, not client media spend.",
 "runway":"Agency Career's estimate of how long current operating cash and permitted credit could support the current company burn plan. It includes recurring obligations and, after an affiliate pivot, planned company-funded media. It is a warning gauge, not a promise: collections, hiring, budgets, equipment, events and incidents can change it.",
 "insolvency":"The agency's inability to pay obligations due with operating cash and permitted credit. Insolvency is a liquidity failure, not simply an unprofitable month; Agency Career ends immediately if the month-close obligations remain unpaid after available credit is applied.",
 "retainer":"A recurring fee paid for the agency's service and availability. To The Moon records it as agency revenue when earned. It is not the client's media budget, platform bill, business sales revenue or collected cash until its receivable is paid.",
 "payroll":"The agency's recurring employee-wage cost. Agency Career shows wages separately from employer taxes and benefits so the full cost of hiring is visible. Neither line is media spend, and failing to cover them is a liquidity problem even when client work is profitable on paper.",
 "modeled contribution":"Modeled earned value minus the media and operating costs included in the displayed scope. It is an amount, while ROI is that profit divided by its cost base; neither is automatically cash.",
 "projected contribution":"Modeled outcome value minus adjusted billed media cost and operations cost for the portfolio window. It is projected because some outcome value may still be modeled or receivable; it is not current cash, ROAS, MER, or ROI.",
 "attributed media margin":"Platform-attributed value minus media spend for the same scope and window. It is a currency amount before operating costs — not a percentage, all-in business profit, proof that advertising caused additional outcomes, a receivable or cash. Attributed media return on investment divides this amount by media spend.",
 "marginal mer":"The modeled outcome value produced by an incremental allocation change divided by the additional media spend that change caused. It asks whether the next dollars were efficient, while blended modeled MER averages earlier and later dollars together; use aligned comparison windows because small increments are noisy.",
 "lead":"A prospective customer action, such as a submitted form or inquiry. A lead is not necessarily accepted, qualified, sold, or converted downstream.",
 "lead quality":"The likelihood that a lead satisfies downstream requirements and creates useful business value. High CTR, conversion volume, or a low CPL does not guarantee high lead quality.",
 "acceptance criteria":"The declared downstream rules used to accept, reject, route, or value a lead after it is created. Criteria can include eligibility, geography, duplication, intent, contactability, or buyer-specific requirements.",
 "downstream acceptance":"The share or outcome of leads that pass the applicable acceptance criteria after acquisition. A change here can reduce realized value even when ad delivery and front-end conversion rates are unchanged.",
 "downstream lead fit":"How well acquired leads match the needs that matter after the form is submitted, such as eligibility, intent, geography, contactability, or buyer demand. It is an expected quality relationship rather than a guaranteed acceptance result, so it can improve while CTR falls or weaken while front-end CVR rises.",
 "conversion":"The action the campaign is optimized or evaluated against. It may be a lead, purchase, signup, or another defined business event.",
 "click":"A measurable interaction with an ad. Click volume describes response, not whether the traffic was valuable.",
 "cpc":"Cost per click (CPC): media spend divided by clicks. It is driven by auction price and click-through rate, and says nothing by itself about conversion quality.",
 "settlement":"The point when earned modeled value reaches To The Moon's settled-value ledger. Settlement delay changes timing, not the day the outcome was earned.",
 "settlement lag":"Time between an earned outcome and its appearance in settled value. Compare metrics using aligned windows before reallocating spend.",
 "unsettled":"Modeled value already earned but not yet settled. It is expected in lag modes and should not be mistaken for a performance collapse.",
 "modeled leads":"To The Moon's estimate of underlying lead outcomes for the named scope and window, including leads a platform report may fail to credit. They are simulated business outcomes, not platform claims or cash.",
 "reported lead":"A lead credited by the simulated event source and platform report. Tracking loss can make this lower than modeled leads without changing customer behavior.",
 "reported clicks":"Clicks shown by the simulated platform or measurement path. Tracking anomalies can make them differ from underlying click activity, and click volume alone does not establish lead quality or value.",
 "attribution gap":"The difference between modeled outcomes and platform-attributed claims for the same window. A gap is a measurement diagnostic, not automatic proof of fraud or bad ads.",
 "demand index":"To The Moon's index for how much conversion opportunity exists in a period. It can rise or fall even when you make no changes.",
 "learning phase":"A period when a delivery system has limited evidence after launch or a major change. Results can be more volatile while it rebuilds signal.",
 "training xp":"Training XP is the persistent record of practice for the selected To The Moon training track. Knowledge checks, tutorials, completed scenarios and demonstrated decisions can add XP. In this browser-based build, it stays with that track on this device. It helps show mastery and recommend what to practice next, but it never changes simulation delivery, random outcomes, budgets, platform learning, leads, value, profit, win conditions or challenge scores.",
 "agency capability points":"Agency Capability Points are spendable resources inside one Agency Career save. The player earns them through career growth and spends them in the capability tree to unlock operating options. They can change that career's mechanics, while Training XP only records learning across play and never buys an in-game advantage.",
 "account learning":"The delivery history and optimization signals associated with a platform ad account or its structures. Changing accounts can change performance even when the creative stays the same. To The Moon simplifies behavior that varies by platform and campaign setup.",
 "creative pipeline":"The queue from request or test through build, review, revisions, approval, and readiness to swap into a live ad.",
 "creative test":"A controlled attempt to learn whether a creative idea or variation improves a declared outcome. Testing creates evidence; it does not put an approved asset into delivery automatically.",
 "approval":"Permission for a creative to enter delivery. Approval can concern internal review, rights, or platform policy; those are distinct gates.",
 "compliance hold":"A temporary delivery stop caused by a simulated asset or policy issue. It affects the named scope and is not automatically an account ban.",
 "scaling":"Increasing delivery while watching marginal economics, saturation, fatigue, learning stability, cash, and platform risk — not simply raising every budget.",
 "restate":"A Channel Command relevance edit that changes geographic framing. It can improve conversion relevance, but it does not refresh visual attention or reset fatigue.",
 "recast":"A Channel Command creative change that introduces a new face or treatment and resets attention. It costs more than restating because it replaces the worn presentation.",
 "relevance":"How closely the ad, audience or keyword, offer, and landing experience fit the intended demand. Relevance can improve conversion without creating fresh attention.",
 "slot":"A To The Moon game object that bundles one delivery ad with its active creative, assigned allocation and, when applicable, platform lane. It is not a universal platform object.",
 "offer timing":"How early a value proposition or call to action appears in a video. If it arrives after most viewers leave, conversion efficiency falls.",
 "campaign budget":"A spending cap attached to a campaign or shared across campaigns, depending on the platform. To The Moon may use an account-level cap for playability and labels that simplification when it appears.",
 "targeting":"Rules and signals used to determine which eligible people, searches, placements, or contexts can receive an ad.",
 "objective":"The business outcome or learning purpose a campaign is meant to advance. It determines the appropriate scoreboard and decision window.",
 "campaign intent":"The declared role of a campaign, such as immediate acquisition, reach, learning, demand creation, or retargeting. It should be established before performance is judged.",
 "decision window":"The period of evidence considered before a change is made. It should account for volume, volatility, attribution, and settlement delay.",
 "tracking":"The measurement chain that records actions and connects them to advertising. Tracking changes what is reported; it does not create the underlying customer action.",
 "account roi":"Business profit divided by the declared all-in investment for the account and window. It should not be used to name a single winning ad.",
 "ad roi":"Attributed ad value minus media spend, divided by media spend, for a stated ad and time window. It can diverge from business ROI when attribution is incomplete.",
 "all-in business roi":"Modeled earned value minus media and operating costs, divided by those total costs. This return on investment (ROI) is the win metric in the four single-account challenges.",
 "attributed media roi":"Platform-attributed earned value minus media spend, divided by media spend. It is a reporting lens, not the all-in win metric.",
 "attributed report":"A To The Moon reporting view containing only leads and value credited through the simulated event source and platform rules. It changes reporting, not delivery or customer behavior.",
 "modeled outcome":"To The Moon's estimate of the underlying business outcome for the selected window, including outcomes that may lack clean platform attribution.",
 "media cpl":"Media spend divided by modeled leads for the same window. Operating costs are shown separately.",
 "reported media cpl":"Media spend divided by platform-reported leads for the same window. Tracking loss can inflate it without changing the underlying acquisition.",
 "account view":"The modeled-outcome lens: earned business value and leads, including outcomes no platform can tie back to an ad, compared with all-in investment.",
 "ad view":"An older label for the attributed-report lens: only leads and value the event source or platform credits to ads, compared with media spend.",
 "pixel":"A plain-language label for the tracking tag that reports what people do after an ad click or view. A broken tag changes measurement; it does not itself change To The Moon's modeled customer outcome.",
 "event source":"One specific measurement input that sends observed events for optimization or reporting, such as a pixel, server feed, app SDK, or offline import. An event source can feed a shared event-source cluster, but the individual source and the cluster are not the same object.",
 "reporting key":"An internal identifier used to route or group events, leads, or attributed results in a reporting system. It can be associated with a user, event source, buyer, or account, but those objects should not be assumed to be interchangeable.",
 "attribution":"The rule and tracking chain used to give an ad credit for an outcome. Account revenue can be real even when attribution cannot prove which ad caused it.",
 "modeled outcome value":"A simulated estimate of business value produced under To The Moon's pay-per-validated-outcome contract for a named scope and window. It is the business-outcome ledger — not a platform claim, settled collection, cash balance, profit, MER, ROAS, or ROI.",
 "platform claims":"Conversion value the simulated platforms report for themselves. Cross-platform paths and view-through windows can overlap, so these claims can add up to more than the modeled business value and never create cash by themselves.",
 "cross-account claim":"Platform-attributed value routed to another account through a shared event-source path. It can duplicate or misassign reporting credit, but it does not create another modeled outcome, receivable, collection, or cash entry.",
 "attributed value":"Outcome value that a platform or measurement rule assigns to an advertising touchpoint. It is a number inside an attributed report — not proof that advertising caused additional outcomes, another modeled outcome, a receivable, settled value, profit or cash.",
 "modeled mer":"Modeled marketing efficiency ratio (MER): modeled outcome value divided by media spend for the same initiative and window. It does not subtract media or operating costs, so it is not profit or ROI; modeled value is also not platform-reported credit or collected cash.",
 "blended modeled mer":"Total portfolio modeled outcome value divided by total portfolio media spend for the same window. Blended means the initiatives are combined once without stacking overlapping platform claims. It measures modeled value efficiency, not profit, ROI, liquidity, or cash.",
 "blended mer":"To The Moon's shorter label for blended modeled MER: portfolio modeled outcome value divided by portfolio media spend, without adding overlapping platform claims.",
 "claimed roas":"Platform-claimed value divided by media spend for the same scope and window. Multiple platforms can claim the same outcome, so claimed return on ad spend may exceed modeled business efficiency. It is not profit, return on investment, proof that advertising caused additional outcomes, a receivable or cash.",
 "receivables":"Value already earned or invoiced in To The Moon but not yet collected as cash. In Agency Career, this can include client invoices or affiliate-network payouts. A due-date delay changes liquidity, not when the underlying revenue was earned.",
 "credit line":"The simulated holding company's shared working-capital facility. It is not a native platform shared-budget feature and it is unrelated to attribution credit.",
 "credit limit":"The maximum simulated balance the shared credit facility can support. It is financing capacity, not cash, budget authorization, media spend, or platform-attributed credit.",
 "available credit":"Credit limit minus bills currently held or used by the shared facility. It is buying headroom for future delivery, not cash, unspent budget, profit, or attribution credit.",
 "adjusted billed cost":"Delivered media cost after To The Moon adds billing adjustments and fees. It can be higher than the media-spend number shown by the buying lane.",
 "event-source contamination":"Mixed signals from different simulated advertisers sharing one event-source cluster. It can degrade targeting and route platform claims to the wrong account without creating another modeled outcome.",
 "event-source cluster":"One simulated pool of conversion signals and attribution joins. Multiple platform initiatives for one advertiser can deliberately share it; unrelated verticals sharing it create contamination risk.",
 "signal integrity":"To The Moon's 0–100% purity score for an event-source cluster. Lower integrity means more unrelated signal mixing, weaker modeled delivery efficiency, and more cross-account claim risk; it does not mean the underlying customer outcomes vanished.",
 "attribution-control quality":"Portfolio Command's score for audit and reconciliation strength. Raising it narrows future platform-claim uncertainty and supports signal recovery. It does not rewrite historical claims, create outcomes, settle receivables or add cash.",
 "view-through":"Credit for an outcome after someone saw an ad but did not measurably click it. Useful for reach media, but especially vulnerable to overlap and over-claiming.",
 "attribution claim uncertainty":"The plausible error around a platform-attributed claim when identity loss, delayed events, view-through rules, or overlapping platforms make exact credit unknowable. An audit can narrow future uncertainty and improve decision confidence, but it cannot turn a claim into another customer outcome or rewrite historical value.",
 "event-source mapping":"The routing connection that tells an ad account or initiative which pixel, server feed, app SDK, offline import, or event-source cluster supplies its optimization and reporting signals. A wrong mapping can mix learning or misroute claims; repairing it affects future evidence and may require relearning rather than rewriting history.",
 "attribution view-through audit":"A review of exposure-based conversion claims, including the attribution window, identity match, overlap with click paths and relationship to modeled business outcomes. In Portfolio Command, it narrows future connected TV (CTV) claim uncertainty. It does not create outcomes, cash or retroactive certainty.",
 "business container":"A simulated administrative layer that groups related ad accounts and shared assets. It is above campaigns; changing a creative does not move the account to another business.",
 "advertiser workstream":"One simulated business objective and vertical inside the holding-company mandate. It may run several simultaneous platform initiatives, but concentration and attribution gates still aggregate them as one advertiser.",
 "platform initiative":"A platform-specific ad account and active campaign path inside one advertiser workstream. It owns lane-specific delivery, learning, bids or creative controls; opening one does not create a new advertiser.",
 "workstream mix":"The set of parallel platform initiatives currently serving one advertiser workstream. Adding a lane changes that mix without creating another advertiser or operating company.",
 "buying lane":"A channel-and-platform delivery path with its own auction, targeting, creative, fatigue, demand, and measurement rules. One advertiser can run several parallel initiatives in different lanes.",
 "delivery hierarchy":"The nested delivery objects and their control scope, such as the platform ad account, then campaign, then ad set or ad group, then ad, then creative. A change at one level does not automatically replace the objects above it.",
 "holding company":"The top portfolio layer in Portfolio Command. It owns shared cash, credit, risk and operating constraints across multiple advertiser workstreams.",
 "operating company":"One business represented inside Portfolio Command. It can have several platform initiatives without becoming several businesses.",
 "client seat":"One active agency relationship occupying one place in Agency Career's 75-client roster limit. A seat can contain several campaigns or platform ad accounts, so it must not be counted as a delivery object.",
 "service cadence":"The modeled interval between meaningful operating touches an account needs. Client size and business model change that interval; it is a workload abstraction, not a claim that every real account should be checked on the same schedule.",
 "service debt":"Overdue account attention carried into later workdays after a required service touch is missed. In Agency Career it raises relationship and performance risk; it is operational backlog, not borrowed money or an invoice.",
 "account health":"Agency Career's 0–100 score for an active client account's operating condition. Timely service, incident response, measurement work and creative coverage can protect it; missed work and unresolved incidents can weaken it. Low account health can reduce client outcomes and threaten renewal, but it is separate from client trust, Outcome index, compliance health and a platform account's status.",
 "outcome index":"Agency Career's smoothed, 100-centered indicator of how strongly a client account is producing modeled business value against its baseline. Service coverage, account health, channel capability, creative readiness, systems, operating breadth and daily variance can move it. An index above 100 can support a performance bonus, but the number is not revenue, ROI, MER, profit or a platform-reported metric.",
 "focus units":"Agency Career's simplified measure of hands-on work capacity. Servicing an account or resolving an incident consumes units according to complexity; one unit is not a literal hour, employee, campaign, or ad account.",
 "capacity utilization":"Required focus units divided by the agency's available focus units for the period. Sustained utilization above 100% creates backlog and service risk, while spare capacity alone does not guarantee strong performance or client trust.",
 "sprawl penalty":"The modeled context-switching overhead caused by operating beyond the agency's supported number of verticals or channel families. Specialization and systems can reduce it; simply accepting more client seats does not.",
 "cash":"Settled funds available for obligations. Positive modeled economics do not guarantee enough cash when receivables arrive after bills come due.",
 "working capital":"Short-term cash and financing used to pay media and operating obligations before customer, client or network proceeds are collected. In Agency Career, the starting operating reserve is the cash portion of this buffer; available credit is the financed portion. Profitable work can still exhaust working capital when bills arrive before receivables.",
 "receivable collections":"The moment previously earned receivables reach their due date and become available cash. Collection changes liquidity and timing; it does not create another outcome, add new revenue, or improve the campaign that originally earned the value.",
 "credit payment failure":"A cash-flow event in which an adjusted platform bill comes due but available cash and financing cannot cover it. Delivery can pause and learning can erode even when modeled profit is positive. Portfolio Command turns that situation into a crisis ticket and, if it continues, a credit collapse.",
 "receivable haircut":"Value surrendered to receive cash from a receivable earlier than its normal due date, similar to simplified factoring. It can protect working capital at the cost of contribution; it is not media waste, an attribution correction, or proof that the original outcome disappeared.",
 "credit holds":"Adjusted platform bills reserved against the shared simulated credit line until their due dates are paid. They reduce available credit, but they are not cash payments, media budget, or attribution credit.",
 "liquidity":"The ability to meet obligations when they come due using available cash and financing. Agency Career's runway estimates how long the current resources could cover the present cost load; it is a warning, not a promise. If month-close bills exceed operating cash plus available credit, insolvency ends the career even when recognized profit is positive.",
 "concentration risk":"Exposure created when one platform, advertiser, account, or engine carries too much of a portfolio. A failure in that dependency can then affect the whole system.",
 "platform concentration":"The largest platform family's share of portfolio media spend during the current 30-day gate window. It measures delivery dependency by spend and is distinct from advertiser concentration, which uses modeled outcome value.",
 "advertiser concentration":"The largest advertiser workstream's share of portfolio modeled outcome value during the current 30-day gate window. It measures business-engine dependency by modeled value, not platform spend.",
 "resilience":"Paid or operational capacity that allows delivery and billing to survive a disruption. In Portfolio Command, it helps you pass a portfolio gate; it does not create free diversification.",
 "contingency layer":"A paid Portfolio Command safety system. The first layer adds billing-grace days. The second also softens measurement shocks and preserves more learning during a lane migration. It is operating capacity, not media spend or a platform feature.",
 "ops action":"One limited daily nonmedia intervention in Portfolio Command, such as an audit, creative replacement, mapping repair or crisis response. Most actions also use cash or credit, but their cost is recorded as operations cost rather than media spend.",
 "acquisition gate":"A Portfolio Command checkpoint after each complete 30-day block. Performance, measurement, liquidity, advertiser concentration and resilience conditions must all pass together. One failed condition resets the gate streak.",
 "gate streak":"The number of consecutive 30-day acquisition gates that passed every required condition. Any failed gate resets the streak; a strong single day cannot advance it.",
 "crisis":"A Portfolio Command ticket with a stated scope, cause and response tradeoff. A creative issue, account hold, event-source problem and payment failure require different fixes.",
 "affiliate pivot":"An irreversible Agency Career choice that replaces retainers and client service with owned-funnel acquisition and delayed network payouts. Calendar, cash, team, skills, and career profit carry forward, while client seats are released and payout, clawback, concentration, and compliance risks become central.",
 "affiliate signal":"Agency Career's 0–100 score for the usable optimization and measurement evidence in one owned funnel after the affiliate pivot. Stronger signal improves modeled payout efficiency; profitable operation and a signal audit can raise it, while weak delivery can erode it. It is separate from event-source signal integrity, compliance heat, payout validation and cash.",
 "compliance heat":"Agency Career's 0–100 pressure score for the claims, ownership and enforcement exposure of one owned funnel after the affiliate pivot. Lower is safer. More heat reduces modeled efficiency, raises clawback risk and can trigger a delivery review; audits and documented claims can lower it. It is the inverse of a safety score and is distinct from compliance health.",
 "validation":"The affiliate network's review of an owned funnel's modeled payout before the receivable becomes collected cash in Agency Career. Validation can approve the expected amount or remove a portion through a clawback. It does not create another customer outcome, improve media performance or guarantee that every modeled dollar will be paid.",
 "clawback":"A portion of a modeled affiliate payout removed during validation before collection in Agency Career. Clawbacks reduce recognized payout and cash while leaving the original media cost in place; they do not erase the delivery that occurred. Funnel compliance heat and the vertical's risk profile affect the simulated chance.",
 "account hold":"A delivery block at ad-account level. Swapping a creative cannot repair billing, verification, access, or account-level policy status.",
 "learning":"To The Moon's normalized estimate of accumulated delivery signal for the named initiative. The percentage rises as modeled evidence accumulates and can fall after a pause, migration, or structural change. It is a game score, not a live platform metric.",
 "algorithm":"The platform system that decides whether, where and how expensively an ad delivers. In To The Moon, its visible daily mood changes cost per thousand impressions, so you can respond to volatility instead of guessing at invisible dice.",
 "compliance health":"Agency Career's resilience score for substantiation, rights, disclosures, funnel integrity, and policy-ready operations. A high score reduces modeled enforcement exposure but is not platform approval, legal advice, or immunity from review.",
 "creative rarity":"To The Moon's game-like summary of a creative card's modeled upside, scale room, and fatigue risk. Common, Epic, and Legendary are game tiers, not industry classifications or guarantees of quality or profit.",
 "common":"To The Moon's baseline creative-rarity tier. A Common card can still be profitable; the label describes its modeled range, not its format, production quality, or a guaranteed outcome.",
 "epic":"A less frequent To The Moon rarity tier with more modeled upside and scale room than Common. It is a game mechanic, not an industry label or a promise that the creative will win.",
 "legendary":"To The Moon's rarest creative tier, modeled with the highest breakout upside and greater burnout risk. It is not an industry label or a guarantee of profit.",
 "creative format":"To The Moon's compact label for how a concept is executed. The expanded catalog also includes placement-led styles, persuasion structures, and production methods, so every card names its actual classification. Format changes lane fit, response, downstream quality, fatigue, volatility, and production burden; it remains separate from concept, rarity, ad, campaign, and account.",
 "story ad":"A vertical, full-screen, Stories-first execution built around an immediate opening and action. It is a placement-led format: It usually fits short mobile feeds better than desktop or long-form inventory, and repeated hooks fatigue quickly in To The Moon.",
 "vsl":"Video sales letter (VSL): a sequenced persuasion structure that moves through a problem, mechanism, proof, offer, and action. It asks for more production and patient attention, then can qualify higher-intent viewers downstream.",
 "podcast creative":"A host, guest, or interview-style creative — not podcast inventory. Conversational proof can build authority and trust, while captions, sound, and sufficient context determine whether the treatment survives a feed placement.",
 "slideshow":"A lightweight sequence assembled from stills, text, and simple motion. Modular parts make it inexpensive to vary across messages and aspect ratios, with less cinematic depth than a fully produced video.",
 "veo creative":"A video execution produced with a generative-video workflow such as VEO. VEO describes the production method, not an ad placement; To The Moon gives it fast variation and novelty alongside elevated execution variance, disclosure, rights, and trust-review pressure.",
 "news greenscreen":"A presenter-led creative that reacts to a headline, source, or visual behind the speaker. Topical relevance can create a sharp opening, while stale context, source clarity, claims, and misleading-news cues create fast decay and review pressure.",
 "nat geo documentary":"A shorthand creative concept for a cinematic nature-documentary-style field story; it does not imply affiliation with a publisher. To The Moon models slow opening attention, durable trust, high production burden, and strong long-form or reach-media fit.",
 "memes":"Culturally recognizable jokes, reactions, or visual grammars used as ad creative. They can be cheap and highly responsive, while tone risk, context drift, downstream quality, and very fast fatigue make them volatile.",
 "voicemail creative":"An audio-led recorded-message or voicemail-screen conceit that opens a curiosity loop. It is a creative style rather than a native platform format and depends on captions, sound design, and frequent new setups.",
 "static":"One still image with copy. Static is inexpensive, stable, and easy to split-test across messages and sizes, but cannot use motion or audio to win the opening moment.",
 "animation":"Designed motion used to demonstrate change, explain a mechanism, or build a reusable visual system. It normally costs more than a static or slideshow and can travel across many video placements when recut correctly.",
 "branded creative":"A polished execution whose advertiser identity is unmistakable. It can build clarity, trust, and durable recall while feeling less native — and generating less immediate click impulse — when it is not adapted to the surrounding feed.",
 "native long-copy":"A long written argument intended to be read in or beside the feed. It can qualify patient readers and build downstream intent, while truncation and short-video behavior reduce its advantage in fast visual placements.",
 "long-copy to video":"A written long-form argument rebuilt as narration, chapters, visuals, and cutdowns. It preserves explanatory depth and expands video reach, but requires additional editing and new hooks for shorter placements.",
 "static image":"A single still-image creative. It is usually fast to produce and multiply, with steadier fatigue than person-led motion, but its outcome still depends on concept, audience, placement, and offer.",
 "rendered scene":"An illustrated or 3D creative built to be recast across people, places, colors, sizes, and treatments without a new physical shoot.",
 "motion graphic":"An animated visual or typographic unit. Motion can win attention quickly, while repeated exposure can exhaust the hook faster than a static treatment.",
 "ugc video":"User-generated content (UGC) video: a person-led, platform-native treatment. It can earn strong attention and breakout scale, but neither the format nor a high rarity guarantees lead quality or profit.",
 "founder / explainer":"A trust-building person-led or narrated explanation. It often trades lower immediate response for stronger downstream fit and slower fatigue.",
 "native display creative":"A deliberately content-like or utilitarian display treatment designed to fit surrounding inventory. It is a creative treatment, while native inventory describes where it runs.",
 "input / ui utility":"A screenshot, form, calculator, bill, quote box, or interface-like creative that makes the next action concrete.",
 "lifestyle static":"A still scene organized around a life event, audience, or place. Relevance and downstream fit normally matter more than raw click rate.",
 "ctv spot":"A connected TV (CTV) spot: a full-screen video creative designed primarily for reach and modeled view-through outcomes rather than dependable click response.",
 "search text / assets":"Headlines, descriptions, and eligible search assets matched to expressed intent. Search uses relevance, bids, query demand, and conversion quality rather than social-style rarity.",
 "creative swap":"Replacing the creative carried by an existing ad or To The Moon slot. The slot keeps its assigned allocation and platform lane; the replacement starts with fresh fatigue and its own economics.",
 "campaign":"A platform delivery container that declares an objective and organizes subordinate delivery objects. Its controls and exact position vary by platform — for example, audience or placement rules may live at campaign, ad-set, ad-group, ad-squad, or line-item level. Changing a creative does not automatically create a new campaign.",
 "dedicated campaign":"A campaign created to give one ad group or initiative independent structural controls, such as budget or delivery pacing. Moving an existing group into one can improve control and diagnostic clarity, but the move does not make its keyword, ad copy, landing page, or accumulated evidence better by itself.",
 "campaign delivery pacing":"The rule for how a campaign attempts to distribute an authorized budget over time. Search Desk models historical standard and accelerated choices. Pacing changes when spend is sought, budget sets the ceiling and a bid changes auction aggressiveness.",
 "ad rotation":"The rule that distributes eligible delivery among multiple ads in the same group. Search Desk uses equal rotation so sibling-copy evidence stays readable, but equal exposure is not guaranteed in live optimized delivery. Equal rotation alone also does not make a test conclusive.",
 "ad group":"A search-campaign grouping of related keywords and ads. Tight themes make the relationship among intent, query, ad, and landing experience easier to manage.",
 "keyword":"A paid-search targeting input representing the search intent an advertiser wants to enter. Match behavior, negatives, bids, and relevance shape when it can serve.",
 "bid":"A control that expresses how aggressively a buyer competes in an auction. The usable level and unit depend on the channel and bidding strategy. Search Desk simplifies it to a manual maximum cost per click (Max CPC).",
 "match type":"A paid-search control for how a keyword can relate to a search. Search Desk uses a deliberately simplified 2017 rule set rather than current platform behavior.",
 "exact match":"Search Desk's narrowest 2017-style match: The purchased keyword or a close variant can trigger the ad. It trades potential volume for tighter intent.",
 "phrase match":"Search Desk's middle 2017-style match: The purchased phrase appears in the search. It allows more volume and some additional waste.",
 "broad match":"Search Desk's widest 2017-style match: Related searches can trigger the ad. It creates the most volume and junk-query risk.",
 "negative keyword":"A search term excluded from eligibility. Reviewing actual queries and adding relevant exclusions can reduce wasted clicks.",
 "search terms report":"The searches that actually triggered ads, distinct from the purchased keyword list. It supplies evidence for negatives, structure, and intent diagnosis.",
 "quality score":"A 1–10 keyword-level paid-search diagnostic built from expected click-through rate, ad relevance and landing-page experience. It helps you find a weak part of the search experience; it is not a key performance indicator or a literal auction-time input. Search Desk derives a simplified score from those three components and lets each one affect its 2017-style auction.",
 "expected ctr":"A Quality Score component that estimates how likely an ad is to earn a click when it is eligible to show. It is an expectation, not the ad's measured click-through rate. Search Desk models it separately, so a copy change can improve the forecast before enough new delivery evidence accumulates.",
 "ad relevance":"A Quality Score component that diagnoses how closely the search ad's wording answers the intent represented by its keyword. It is distinct from expected CTR and landing page experience: an attention-getting ad can still promise the wrong thing.",
 "landing page experience":"A Quality Score component that diagnoses whether the destination is relevant, useful, and easy to use for the searcher's intent. It evaluates the post-click handoff, not the bid or the wording of the ad itself.",
 "expanded text ad":"A historical Google Search format represented in Search Desk with two headlines and one longer description, matching its 2017 setting. To The Moon does not imply that new expanded text ads can be created or edited in current Google Ads.",
 "a/b ad permutation":"A controlled sibling ad that preserves the core message and changes one declared copy axis, such as a benefit, proof point, or call to action. Each variant gathers its own evidence. It differs from a full rewrite, which replaces the lead ad with substantially different wording.",
 "avg position":"A 2017 placement metric used only by Search Desk. Google retired the live metric in 2019; To The Moon retains it to represent that historical period.",
 "max cpc":"The highest click price allowed by Search Desk's simplified manual-bid control. It applies at the ad-group level in this challenge.",
 "sis":"Search impression share (SIS): the portion of eligible search impressions that received an impression. Search Desk treats it as supporting diagnostic evidence.",
 "impression share":"The portion of eligible impressions that received an impression. Search Desk separates the share lost to rank from the share lost to budget because they require different responses.",
 "query ceiling":"The finite amount of eligible search demand available at a given time. Once that ceiling is approached, a larger authorization cannot force additional relevant searches into existence.",
 "sis lost to rank":"Eligible search share missed because bid or relevance was insufficient. In Search Desk, improve the bid or relevance rather than the budget.",
 "sis lost to budget":"Eligible search share missed because the budget was exhausted. In Search Desk, improve the budget rather than the bid.",
 "auction rank":"An ad's relative ability to enter and win useful placement in an auction, shaped by bid, relevance or quality signals, competition, and context. Low rank is not the same as a depleted budget: paying more may help, but improving relevance or choosing better intent can be the more efficient response.",
 "wasted clicks":"Paid search clicks from queries that are unlikely to advance the declared campaign objective, often because intent, geography, service, or eligibility is wrong. Search-term review and negative keywords can reduce obvious waste, but research traffic should not be excluded automatically when it has a measured role.",
 "brand keyword conquest":"A competitor's attempt to capture branded search demand created around another advertiser. Brand protection can preserve that demand with funded, relevant search coverage, but the resulting conversions should not automatically be credited wholly to search when another channel created the initial interest.",
 "accelerated delivery":"A historical Search Desk pacing choice that spends as quickly as available demand permits. It represents the 2017 setting, not current platform availability.",
 "standard delivery":"Search Desk's historical control for pacing a daily budget across the day.",
 "compliance":"The operating discipline that checks policy, claims, disclosures, rights, and usage constraints before and during delivery.",
 "review":"A defined approval or investigation step. Creative review, account review, billing review, and access review affect different scopes and should not be treated as interchangeable.",
 "cpa":"Cost per acquisition (CPA) — spend divided by conversions. It is the search-era sibling of cost per lead (CPL).",
 "roas":"Return on ad spend (ROAS): the declared attributed revenue or value divided by media spend for the same scope and window. A 2.00× ROAS means two units of value per unit spent; it does not subtract cost or prove that advertising caused additional outcomes.",
 "intake":"The initial operating conversation in which the baseline, objective, measurement source, constraints, decision rights, and expectations are established.",
 "client trust":"A weighted relationship score built from five trust dimensions: results, judgment, transparency, responsiveness, and alignment. Each simulated client weights those dimensions differently, so the same interaction can move the overall score by a different amount. It is separate from media performance, client tension, and any single conversation.",
 "trust dimensions":"The five components behind Classic mode's client-trust score: results, judgment, transparency, responsiveness, and alignment. They separate what the work delivered from how decisions, uncertainty, follow-through, and business priorities were handled.",
 "client insight":"Progress earned by noticing a client's observable cues, testing a response, and learning from the reaction. More insight makes the Client Read more specific; it never reveals a guaranteed script or replaces the account evidence.",
 "client read":"To The Moon's progressively revealed, evidence-based hypothesis about a simulated client's working preferences and concerns. It summarizes observed interactions rather than diagnosing a person, and it can refine or contradict the initial business prior.",
 "client tension":"Short-term pressure in the client relationship during a difficult moment. Tension can rise quickly after a surprise or unsupported claim and fall after a clear, owned response; it is not the same as long-term client trust or campaign performance.",
 "communication stance":"The job a response is trying to do: recommend an action, investigate uncertainty, acknowledge impact, or establish a boundary. Stance affects how a message lands, but factual support and operational judgment remain more important than stylistic fit.",
 "business prior":"A tentative starting hypothesis based on the simulated business context — for example, that a finance-led organization may ask for causal evidence. It is a clue, not a personality label or rule, and later observations should update it.",
 "working agreement":"An explicit operating expectation such as who owns an action, when it is due, what evidence will be reported, or which threshold triggers a change. It turns a reassuring conversation into something the relationship can verify later.",
 "commitment":"A promised follow-up recorded by To The Moon, such as checking tracking, adding negative keywords, rewriting copy or reporting at the next checkpoint. Meeting or missing it affects the relationship once; saying the right words is not the same as completing the work.",
 "relationship risk":"The chance that repeated surprises, unowned work, unsupported claims, unresolved tension, or declining trust will change the client's budget or retention decision. It is an operating consequence, not proof that the media itself is performing poorly.",
 "baseline":"The agreed starting level for a metric — for example calls, forms, sales, spend, or acceptance rate — used for comparison. A target can be incremental or ambitious, but its timeframe, evidence, and constraints should be explicit.",
 "monthly conversion pace":"A projection of the current conversion rate across a 30-day month, usually calculated from outcomes so far divided by elapsed days. It helps compare progress with a monthly goal, but a short, delayed, or under-reported window can make the projection unstable; pace is not a promise of the final total.",
 "client retention line":"The profile-specific client-trust threshold used by Classic mode when evaluating retention and future budget authority. Crossing it is a relationship warning rather than proof that the ads failed, and real clients do not share a universal numerical cutoff.",
 "campaign source of truth":"The agreed dataset and definition used to make a campaign decision — for example, validated customer records, collected revenue, a platform report or a reconciled business ledger. A source can answer one question well yet be too delayed or narrow for another, so state its scope and decision window.",
 "test stop rule":"A condition defined before a test that says when to end, pause, or call the comparison, such as a minimum evidence level, maximum acceptable loss, time limit, or decision threshold. It protects against chasing early noise, but a rigid rule should still account for delayed outcomes and material operational risk.",
 "causal test evidence":"Evidence from a comparison designed to isolate whether a particular change produced the observed result. Holding other variables stable, randomization, matched cohorts, or carefully timed holdouts strengthen the claim; a before-and-after dashboard change alone usually supports a hypothesis, not certainty.",
 "in-window":"Inside the stated date range. A campaign can be negative in-window while serving a longer-horizon role, so the phrase should describe timing rather than permanent performance.",
 "band":"A normal diagnostic range for a metric in a particular account and window. It is context for investigation, not automatically a pass/fail threshold.",
 "funnel":"A set of connected measurement stages whose arrows must match the actual denominator. In the four single-account challenges, impressions lead to ad clicks. Those clicks feed two displayed branches: modeled click-to-lead outcomes and a separate landing-visit to on-page-action diagnostic. Landing-page click-through rate is not multiplied into conversion rate.",
 "landing-page visit":"An arrival at, or successful load of, the destination page after an ad interaction. It is a separate funnel stage from the ad click and from any action taken on the page.",
 "on-page click":"A click or declared action taken after a landing-page visit, such as opening an offer or continuing a form. It is not the original ad click; LP CTR uses this action in To The Moon's parallel landing diagnostic, not as a required step in its click-to-lead model.",
 "fatigue":"The loss of response that can occur when the same creative is repeatedly exposed to an audience. To The Moon models fatigue as a rising state with format- and rarity-specific effects; real-world pace and symptoms vary.",
 "saturation":"A limit in fresh eligible audience or inventory. Additional budget in the same slot can buy increasingly expensive or lower-quality delivery, causing marginal performance to weaken.",
 "multiplication":"Expanding a promising concept into deliberate variations across useful axes such as hook, audience, geography, offer, size, or treatment. One-variable tests can isolate causality, while structured matrices can explore combinations when the design and volume support them.",
 "axis":"One controlled creative variable, such as color, geography, size, demographic framing, or offer. Several usable axes make a concept easier to expand methodically.",
 "axes":"Plural of axis: the controlled variables used to create variations of a working concept.",
 "trap":"An ad that looks like a winner on engagement and loses money anyway, usually because its leads are worth little. Slot 3 is one on purpose.",
 "brand play":"Spend evaluated against reach, awareness, demand creation, or a longer decision window rather than immediate attributed profit alone. It may support later efficiency or value, but that effect should be measured rather than assumed; To The Moon models this role explicitly.",
 "reach":"How many different people saw it, as opposed to how many times it was shown. Cheap reach is what a brand play is buying.",
 "noise":"Random or unexplained movement that can obscure the effect of a decision. Its size depends on volume, market, metric, and window, so one period is usually weak evidence rather than an automatic reason to act.",
 "variance":"The spread in results caused by randomness rather than a strategy change. Replaying a fixed seed holds the random sequence constant so decision effects are easier to compare.",
 "seed":"The run number in the corner. It fixes every random roll, so the same seed replayed means a better result came from a better decision.",
 "matrix":"One idea built out across every combination of its variables — five colors by five states is a 25-asset matrix.",
 "cut":"A version of a creative made for one slice: a state cut, a language cut, a 16x9 cut. Same story, re-pointed.",
 "native":"Ad inventory designed to sit within the surrounding content experience. Plain or content-like creative can fit that context, but performance still depends on placement, message, audience, offer, and downstream quality.",
 "demand gen":"A visual Google advertising lane represented in To The Moon as interruption or demand-stimulation media rather than expressed search intent. The game uses simplified delivery rules, not a live-platform benchmark.",
 "display":"Visual ad inventory across websites and apps, commonly bought directly or programmatically. Pricing and quality vary widely, so evaluate viewability, response, conversion quality, cost per outcome, and attribution rather than assuming impressions are cheap.",
 "audience":"The group of people an ad is aimed at.",
 "demo":"Short for demographic — the slice of people a version is cast for, like seniors or 35-plus.",
 "vertical":"The product line an ad sells, for example auto or home.",
 "concept":"The idea behind an ad — the scene, the mechanic, the promise. One concept can become dozens of assets.",
 "creative":"The customer-facing image, video, copy, audio, or asset combination carried by an ad. The ad is the delivery object; the creative is what people experience.",
 "asset":"One deliverable file at one size. A concept is an idea; an asset is a file.",
 "hook":"The first beat that stops the scroll — the thing that earns the second of attention.",
 "mechanic":"The repeatable device a concept runs on: a bill screenshot, a price reveal, a street scene. Mechanics travel between concepts.",
 "placement":"Where the ad actually ran. The same creative in two placements can perform very differently.",
 "tail":"The long list of small ads under the handful that carry the account.",
 "decay":"A winner slowly getting worse as it fatigues or its audience saturates.",
 "milking":"Running a proven ad for the profit it still makes while not expecting it to grow.",
 "geo cut":"A creative version adapted for a place such as a state, county, city, or region. Geographic relevance can help when the market, offer, and message support it, but it is not a universal performance multiplier.",
 "broad":"No targeting narrowing, and no single place — the version that runs everywhere.",
 "front end":"The exposure and click-response part of the funnel: cost per thousand impressions (CPM), click-through rate (CTR), and cost per click (CPC).",
 "lander":"The page an ad sends people to. Landing-page click-through rate (LP CTR) measures the lander's pull, not the ad's.",
 "cpm":"Cost per thousand impressions (CPM) — what it costs to be seen.",
 "ctr":"Click-through rate (CTR): clicks divided by impressions. It measures attention, not value.",
 "cvr":"Conversion rate (CVR): completed conversion events divided by the stated eligible denominator. In the four single-account challenges, the displayed CVR is leads divided by ad clicks; other systems may use visits, sessions or users.",
 "cpl":"Cost per lead (CPL): the declared cost base divided by leads in the same window. The interface labels whether the cost base is media-only or all-in.",
 "landing-page optimization":"An action in the four single-account challenges that improves the landing step. Each use raises landing-page click-through rate by 5 percentage points and overall click-to-lead conversion rate by 8%, up to two uses.",
 "epl":"Earnings or value per lead (EPL): the declared earned value divided by leads for the same scope and window. It belongs beside CPL, acceptance, and settlement timing; no single metric captures the whole business.",
 "lp ctr":"Landing-page click-through rate (LP CTR): the share of landing-page visitors who took To The Moon's declared on-page action. In the four single-account challenges, it is a separate landing diagnostic. Leads are modeled directly from ad clicks through conversion rate, so LP CTR is not multiplied into lead volume.",
 "roi":"Return on investment (ROI): profit divided by the declared investment for the same scope and window. The cost base and value window must be stated; account ROI and ad ROI can therefore answer different questions.",
 "impressions":"How many times the ad was shown."
};
const KNOWLEDGE_DB=Object.freeze({
  version:2,
  note:"Use this guide for definitions, decision steps and examples from To The Moon. Historical rules and game-only mechanics are labeled when they appear.",
  lessons:[
    {id:"01",title:"Creative architecture",summary:"Separate the idea, execution, and deliverable so successful advertising can be expanded deliberately.",
      foundation:"A concept is the central idea. A mechanic is the repeatable device that expresses it. A hook earns attention. Creative is what the audience experiences; an asset is one finished file.",
      working:"Document each concept's usable axes — audience, geography, offer, format, size, treatment, or opening hook. Build cuts and matrices from proven concepts instead of treating every asset as a new idea.",
      expert:"A useful creative system preserves the winning mechanism while isolating meaningful variables. Tests that change several axes at once can create lift without revealing which change caused it.",
      checklist:["Name the concept and mechanic.","Identify the hook and intended audience.","Record which axis each variation changes.","Keep concept-level and asset-level results separate."],
      terms:["concept","mechanic","hook","creative","asset","cut","matrix","axis","placement"]},
    {id:"02",title:"Iteration, fatigue, and saturation",summary:"Expand proven ideas while distinguishing worn-out creative from exhausted audience capacity.",
      foundation:"Fatigue means the same creative has lost attention. Saturation means the available audience or inventory has become expensive to reach. They are related but require different responses.",
      working:"A creative test creates an option; a creative swap puts that option into delivery. Restating can improve relevance without refreshing attention, while recasting or replacing creative resets fatigue.",
      expert:"Scaling should follow marginal economics rather than headline averages. Creative decay, audience overlap, auction pressure, and rapid structural changes can make the next unit of spend less valuable than the previous one.",
      checklist:["Diagnose fatigue separately from saturation.","Keep replacement creative ready before burnout.","Scale in measured steps.","Compare marginal performance after each change."],
      terms:["creative test","creative swap","ad rotation","creative rarity","common","epic","legendary","fatigue","saturation","fresh capacity","creative scale pressure","lane capacity pressure","rapid-scale review risk","decay","multiplication","restate","recast","scaling"]},
    {id:"03",title:"Purpose before scoreboard",summary:"Performance only becomes meaningful when the campaign's purpose and measurement scope are known.",
      foundation:"A campaign can be designed for immediate profit, learning, reach, demand creation, or conversion. Negative in-window profit does not automatically mean it failed.",
      working:"Modeled outcome compares earned business value with all-in investment. Attributed report compares platform-creditable value with media spend. They answer different questions and must keep their windows and cost bases visible.",
      expert:"Portfolio roles should be evaluated against intended contribution and decision horizon. Causal lift, downstream effects, attribution loss and learning value can matter even when a platform report looks weak.",
      checklist:["State the objective.","Confirm the evaluation window.","Identify the measurement lens and cost base.","Ask what the spend is intended to accomplish before changing it."],
      terms:["objective","campaign intent","account view","ad view","account roi","ad roi","brand play","learning","in-window","reach","profit"]},
    {id:"04",title:"Funnel diagnosis",summary:"Read each declared measurement path with its denominator so the location of a problem is clear before an intervention is chosen.",
      foundation:"In the four single-account challenges, the outcome path runs from impressions to ad clicks and then to modeled leads. Ad clicks also feed a separate landing diagnostic that runs from landing-page visits to on-page actions. Each rate must name its numerator and denominator; do not multiply the two branches together.",
      working:"Cost per thousand impressions (CPM) prices exposure. Click-through rate (CTR) measures ad response. Landing-page click-through rate (LP CTR) measures an intermediate landing-page action. The displayed conversion rate (CVR) remains overall clicks to leads. LP CTR is diagnostic; it is not multiplied into CVR a second time. Cost per lead (CPL) combines upstream media cost and the lead outcome.",
      expert:"Aggregate rates can hide changes in traffic mix, placement, lead quality, downstream acceptance, settlement or lead value. Diagnose both the rate and denominator, then segment only when enough volume exists. The landing-page action in the four single-account challenges is an explicit intervention; it is not another funnel multiplier.",
      checklist:["Find the first stage that changed materially.","Check its denominator and volume.","Compare the stages before and after the break.","Do not repair a landing-page problem with a creative change."],
      terms:["funnel","impressions","click","landing-page visit","on-page click","lead","lead quality","acceptance criteria","downstream acceptance","downstream lead fit","conversion","cpm","ctr","lp ctr","cvr","cpl","lander"]},
    {id:"05",title:"Signal, noise, and decision windows",summary:"Separate persistent movement from ordinary volatility before reallocating budget.",
      foundation:"Daily results move even when strategy is unchanged. One favorable or unfavorable period is weak evidence by itself.",
      working:"Use recent movement, adequate conversion volume, settled outcomes, and the account's normal band before acting. A fixed seed holds the random sequence constant so decisions can be compared fairly.",
      expert:"A decision window should reflect conversion delay, seasonality, auction volatility, effect size, and acceptable error. A longer window reduces noise but can react too slowly to a genuine break.",
      checklist:["Check whether outcomes have settled.","Compare several periods rather than one.","Confirm volume supports the conclusion.","Record the hypothesis before changing allocation."],
      terms:["noise","variance","seed","settlement lag","decision window","band","test stop rule","causal test evidence"]},
    {id:"06",title:"Metric fluency",summary:"Use each metric for the question it can answer and preserve the correct denominator.",
      foundation:"Click-through rate (CTR) measures attention. Cost per lead (CPL) and cost per acquisition (CPA) measure acquisition cost. Earnings or value per lead (EPL) measures value per lead. Return on investment (ROI) measures profit relative to cost. Return on ad spend (ROAS) measures value relative to media spend. Agency profit uses agency fees and agency costs; client media spend belongs to the client's campaign economics. Agency Career's Outcome index is a 100-centered performance indicator, not another form of revenue or ROI.",
      working:"A high click-through rate (CTR) can coexist with poor economics. Cost per lead (CPL) belongs beside earnings or value per lead (EPL) or conversion value. Modeled marketing efficiency ratio (MER) is modeled value divided by media spend; return on ad spend (ROAS) is attributed or claimed value divided by media spend; neither subtracts cost. Contribution is an amount, while return on investment (ROI) divides profit by its stated cost base. Retainers, payroll, and receivables must stay on the agency ledger instead of being blended into a client's ad-spend result. After the affiliate pivot, validation and clawbacks determine how much modeled payout becomes collected cash.",
      expert:"Reported metrics depend on attribution rules, timing, cohort maturity, aggregation level, and cost scope. Modeled outcome value, platform claims, projected contribution, settled value, receivables, and cash can all differ while remaining internally consistent. Platform claims should not be added as if each platform created a separate outcome, and pass-through client media should not be presented as agency revenue.",
      checklist:["Name the numerator and denominator.","Confirm scope and date window.","Label modeled, claimed, settled, or collected value.","Separate client media from agency fees and costs.","Pair cost with outcome quality.","Do not substitute engagement for business value."],
      terms:["media spend","client media spend","revenue","settled value","profit","agency profit","operations cost","operating reserve","monthly operating statement","monthly operating obligations","retainer","payroll","receivables","working capital","liquidity","runway","insolvency","modeled contribution","projected contribution","attributed media margin","roi","roas","claimed roas","modeled mer","blended modeled mer","marginal mer","cpl","cpa","epl","platform claims","outcome index","validation","clawback","training xp"]},
    {id:"07",title:"Measurement and attribution",summary:"Treat tracking as evidence about outcomes, not as the system that creates those outcomes.",
      foundation:"A pixel or event source reports actions after ad exposure. Attribution applies rules that assign credit. A tracking failure can change reported results without changing customer behavior.",
      working:"When modeled and attributed totals diverge, inspect tracking, reporting-key routing, and attribution before pausing ads. Repair affects future reporting; it does not rewrite the historical gap.",
      expert:"Cross-platform paths, view-through windows, delayed events, duplicated claims, consent loss, and event-source contamination can produce incompatible reports. Reconciliation separates modeled outcomes, cross-account claims, settled value, receivables, cash, and platform claims without rewriting history.",
      checklist:["Compare modeled with attributed totals.","Check event health and settlement timing.","Identify the attribution rule and window.","Do not manufacture value by summing overlapping claims."],
      terms:["pixel","tracking","reporting key","attribution","modeled outcome value","platform claims","cross-account claim","view-through","attribution view-through audit","attribution claim uncertainty","attribution gap","event-source mapping","event-source contamination","signal integrity","attribution-control quality","settlement","settled value"]},
    {id:"08",title:"Discovery, client judgment, and operating context",summary:"Establish the business facts, then learn how a client makes decisions without turning context into a stereotype.",
      foundation:"The same dashboard can represent an in-house team, agency relationship, lead-generation account, growth mandate, or brand program. Start with the objective, baseline, source of truth, constraints, and decision rights. In Classic mode, the business type supplies an uncertain business prior — a useful first question, not a personality label. Client trust is also not one vague feeling: it combines results, judgment, transparency, responsiveness, and alignment, while client tension tracks shorter-term pressure. In Agency Career, account health tracks operating condition while trust tracks the relationship; one can weaken before the other.",
      working:"Use this loop during a tense interaction: observe, form a hypothesis, respond and update your understanding. Read the account facts and the client's observable cue, choose whether the moment calls for a recommendation, investigation, acknowledgment or boundary, then inspect the reaction. The resulting Client Read becomes more specific as client insight accumulates and may reinforce or contradict the business prior. Evidence and operational judgment come first: A well-supported answer can remain responsible even when another stance would have landed more smoothly, while an unsupported promise is not rescued by sounding personally compatible. Convert the response into a working agreement with an owner, action, evidence check, timing and service cadence. To The Moon remembers commitments and service debt after the conversation closes.",
      expert:"Treat relationship learning as Bayesian and behavioral rather than diagnostic: begin with a low-confidence contextual prior, update only from observable reactions, and preserve uncertainty. Avoid three failure modes — stereotyping from business type, appeasing a preferred style at the expense of truth, and gaming the trust score with language that is not followed by action. Multi-dimensional trust explains why a client can respect analytical judgment yet still lose confidence in responsiveness, or accept weak short-term results when transparency and the recovery plan are strong. Client tension can spike before durable trust changes, creating an opportunity to de-escalate without hiding risk. Strong operating agreements define budget authority, approval rights, service expectations, attribution rules, risk limits, escalation paths, and what happens when a commitment is missed; those controls reduce relationship risk and analytical error at the same time.",
      checklist:["State the business objective, baseline, source of truth, and decision window.","Treat the business prior as a question to test, not a conclusion.","Separate the account facts from the client's observable cue.","Check the service cadence and overdue service debt.","Keep evidence and operational judgment ahead of style matching.","Name the owner, next action, evidence check, and timing.","Review the reaction and update the Client Read without overgeneralizing.","Close or renegotiate every commitment instead of letting it disappear."],
      terms:["intake","baseline","monthly conversion pace","campaign source of truth","business prior","client trust","trust dimensions","client tension","communication stance","client insight","client read","working agreement","commitment","client retention line","relationship risk","service cadence","service debt","account health","budget","approval","tracking"]},
    {id:"09",title:"Channel and platform physics",summary:"Choose controls that match how each buying channel finds and converts demand.",
      foundation:"Paid search captures expressed intent by connecting a search, keyword, ad, and destination. Paid social, display, and Demand Gen interrupt or stimulate demand. Programmatic and connected TV (CTV) can emphasize reach and view-through measurement.",
      working:"Search uses keywords, bids, match types, negatives, Quality Score diagnostics, and finite query volume. Read expected click-through rate (CTR), ad relevance, and landing-page experience separately; use an A/B ad permutation to change one copy axis, or a rewrite to replace the lead wording.",
      expert:"Search Desk's expanded text ad is a historical 2017 format with two headlines and a longer description. More copy space does not guarantee lift, and current platform controls differ. Cross-channel interactions also include branded-search lift, audience overlap, impression-share ceilings, auction inflation, view-through uncertainty and concentration risk.",
      checklist:["Classify the lane as intent, interruption or reach-led.","Use controls and metrics that fit the lane.","Check demand ceilings and overlap.","Separate To The Moon's rules from live platform evidence."],
      terms:["paid search","ppc","paid social","programmatic","ctv","display","demand gen","view-through","account learning","audience","keyword","match type","quality score","expected ctr","ad relevance","landing page experience","expanded text ad","a/b ad permutation","ad rotation","dedicated campaign","campaign delivery pacing","auction rank","wasted clicks","brand keyword conquest","sis"]},
    {id:"10",title:"Structure, portfolio, and operating capacity",summary:"Identify the layer being changed, distinguish profitable economics from available cash, and keep organizational growth within service capacity.",
      foundation:"One hierarchy used in To The Moon starts with the platform ad account, then campaign, then ad set or ad group, then ad, then creative. A To The Moon slot bundles an ad with creative; swapping creative does not create a new account or campaign. A client seat represents one agency relationship and can contain several delivery objects. A buying lane describes the channel path, not another hierarchy level.",
      working:"Portfolio mode adds business containers, advertiser workstreams, workstream mixes, platform initiatives, event-source clusters, shared budget, receivables, credit holds, and ops actions. Agency Career adds focus units, capacity utilization, service debt, team roles, and a sprawl penalty for unsupported channel or vertical breadth. Agency Capability Points are spendable inside one career save and unlock options in its capability tree; Training XP remains a separate learning record and cannot buy those options. After an affiliate pivot, each owned funnel adds its own fatigue, affiliate signal, compliance heat, media funding and payout timing. Each control names the layer it changes and the resources it consumes.",
      expert:"Positive projected contribution can coexist with liquidity failure when collections lag adjusted bills. Available credit, cash, modeled value, and profit answer different questions. Shared credit and event sources create cross-account risk that isolated campaign metrics cannot reveal. The affiliate pivot changes the revenue model and risk surface; it does not create a second stack of client fees beside owned-funnel payouts. Affiliate signal describes one funnel's usable evidence and must not be substituted for event-source signal integrity or payout validation.",
      checklist:["Name the hierarchy level being changed.","Separate a client seat from its platform ad accounts.","Compare required focus with available capacity.","Separate authorization, spend, billed cost, contribution, and cash.","Track receivable and available-credit timing.","Check concentration and sprawl before expanding."],
      terms:["account","platform ad account","client seat","campaign","ad set","ad group","ad","slot","delivery hierarchy","buying lane","platform initiative","advertiser workstream","workstream mix","business container","holding company","operating company","budget","allocation","focus units","capacity utilization","sprawl penalty","agency capability points","training xp","affiliate pivot","affiliate signal","operations cost","operating reserve","monthly operating statement","monthly operating obligations","runway","insolvency","credit line","credit limit","available credit","credit holds","working capital","receivables","receivable collections","receivable haircut","credit payment failure","cash","liquidity","platform concentration","advertiser concentration","resilience","contingency layer","ops action","acquisition gate","gate streak"]},
    {id:"11",title:"Asset rights, policy, and review",summary:"Treat inspection and approval as media operations, not as a final cosmetic check.",
      foundation:"An effective asset can still be unusable because of third-party branding, recognizable people, unsupported claims, missing disclosures, or platform policy.",
      working:"Inspect source, rights, likeness, visible marks, pricing language, promises, and required disclosures before shipping. Advanced modes add build time, review, revisions, rejection, holds, replacement planning, and compliance health as a forward-looking operations signal. After the Agency Career affiliate pivot, compliance heat is a risk score: Lower is safer, and unresolved heat can affect payout validation as well as delivery review.",
      expert:"A mature workflow preserves provenance, approval history, usage scope, expiration, substantiation, and platform-specific policy notes. Creative rejection, account restriction, billing hold, and business access failure are distinct incidents. A modeled compliance-health score can prioritize prevention, but it cannot promise approval or replace qualified review. Payout validation and clawbacks are financial review outcomes, not substitutes for platform policy or legal review.",
      checklist:["Verify source and usage rights.","Check people, brands, claims, prices, and disclosures.","Record approval status and limitations.","Monitor compliance health without treating it as immunity.","Keep alternate compliant creative ready."],
      terms:["compliance","compliance health","compliance heat","validation","clawback","review","approval","account hold","asset","creative pipeline"]}
  ]
});
